package com.example.demo;

import java.net.http.HttpClient;
import java.time.Duration;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.http.client.JdkClientHttpRequestFactory;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.client.RestClient;
import org.springframework.web.server.ResponseStatusException;
import static org.springframework.http.HttpStatus.BAD_GATEWAY;
import static org.springframework.http.HttpStatus.BAD_REQUEST;

@RestController
public class SpeechController {
    private final RestClient client;
    private final String voice;

    public SpeechController(RestClient.Builder builder,
            @Value("${elevenlabs.api-key}") String key,
            @Value("${elevenlabs.voice-id}") String voice) {
        var http = HttpClient.newBuilder()
                .connectTimeout(Duration.ofSeconds(3)).build();
        var factory = new JdkClientHttpRequestFactory(http);
        factory.setReadTimeout(Duration.ofSeconds(10));
        this.client = builder.baseUrl("https://api.elevenlabs.io")
                .defaultHeader("xi-api-key", key)
                .requestFactory(factory).build();
        this.voice = voice;
    }

    @PostMapping("/speech")
    public ResponseEntity<byte[]> speak(@RequestBody Text input) {
        if (input.text() == null || input.text().isBlank()
                || input.text().length() > 500) {
            throw new ResponseStatusException(BAD_REQUEST,
                    "Text must contain 1 to 500 characters");
        }
        var response = client.post()
                .uri("/v1/text-to-speech/{voice}?output_format=mp3_44100_128", voice)
                .contentType(MediaType.APPLICATION_JSON)
                .body(new Speech(input.text(), "eleven_multilingual_v2"))
                .retrieve().toEntity(byte[].class);
        byte[] audio = response.getBody();
        MediaType type = response.getHeaders().getContentType();
        if (audio == null || audio.length == 0 || type == null
                || !"audio".equals(type.getType())) {
            throw new ResponseStatusException(BAD_GATEWAY, "No audio received");
        }
        return ResponseEntity.ok().contentType(type).body(audio);
    }

    public record Text(String text) {}
    public record Speech(String text, String model_id) {}
}

package com.example.demo;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

@SpringBootApplication
public class DemoApplication {
    public static void main(String[] args) {
        SpringApplication.run(DemoApplication.class, args);
    }
}
